<script setup lang="ts">defineProps<{nodes:any[]}>();defineEmits(['select'])</script><template><ul class="tree-list"><li v-for="(n,i) in nodes" :key="i"><button class="tree-node" @click="$emit('select',n)"><span>{{n.isDir?'▾':'◇'}}</span>{{n.name||n.path||n}}<small v-if="n.children?.length">{{n.children.length}}</small></button><DirTree v-if="n.children?.length" :nodes="n.children" @select="$emit('select',$event)"/></li></ul></template><script lang="ts">export default {name:'DirTree'}</script>
